import {extractClaims,parseHar,audit,exportReport,reportMarkdown,CATEGORIES,STATUS,MAX_HAR_BYTES} from './engine.js';
import {EXAMPLES} from './examples.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={capture:null,harText:null,fileName:null,claims:[],report:null,sample:null,phase:'input',readVersion:0};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function showError(message){$('#input-error').textContent=message;$('#input-error').hidden=!message;}
function ready(){$('#review-button').disabled=!$('#policy').value.trim()||!state.capture;}
function setStateLabel(text){$('#review-state').textContent=text;}
const emptyHtml=$('#results-content').innerHTML;
function invalidate(){state.report=null;state.claims=[];state.phase='input';$('#results-content').innerHTML=emptyHtml;setStateLabel('INPUT CHANGED · REVIEW AGAIN');ready();}
function setSampleSelection(){document.querySelectorAll('.demo-button').forEach(b=>b.classList.toggle('active',b.dataset.demo===state.sample));}
async function loadHar(file){
 const version=++state.readVersion;if(!file)return;
 try{if(file.size>MAX_HAR_BYTES)throw new Error('Choose a capture smaller than 10 MB.');const text=await file.text();if(version!==state.readVersion)return;const capture=parseHar(text);state.capture=capture;state.harText=text;state.fileName=file.name;state.sample=null;$('#har-label').textContent=file.name;$('#har-help').textContent=`${capture.total} requests · ${capture.destinationCount} destinations · ready to review`;showError('');invalidate();setSampleSelection();}
 catch(error){if(version!==state.readVersion)return;state.capture=null;state.harText=null;state.fileName=null;state.sample=null;$('#har-label').textContent='Choose a HAR file';$('#har-help').textContent='or drop it here · .har / .json · up to 10 MB';invalidate();setSampleSelection();showError(error.message);}
}
function scrollResults(){if(window.innerWidth<761)$('#results-heading').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function loadExample(key){
 const example=EXAMPLES[key];if(!example)throw new Error('Unknown example.');state.readVersion++;state.sample=key;state.harText=JSON.stringify(example.har,null,2);state.capture=parseHar(state.harText);state.fileName=`cedar-${key}.har`;$('#policy').value=example.policy;$('#context').value=example.context;$('#har-file').value='';$('#policy-file').value='';$('#har-label').textContent=state.fileName;$('#har-help').textContent=`${state.capture.total} requests · synthetic example`;showError('');ready();setSampleSelection();reviewClaims();toast('Synthetic example loaded. Review its policy claims.');return {example:key,requests:state.capture.total,claims:state.claims.length};
}
function reviewClaims(){try{if(!state.capture)throw new Error('Add a HAR capture first.');state.claims=extractClaims($('#policy').value);state.report=null;state.phase='claims';renderClaims();showError('');scrollResults();}catch(error){showError(error.message);}}
const modeLabels={deny:'Denies collection / transmission',allow:'Discloses collection / transmission',review:'Needs context — do not decide'};
function renderClaims(){
 setStateLabel('REVIEW BEFORE RUNNING');
 const cards=state.claims.map((c,i)=>`<article class="claim-card"><blockquote>${escape(c.quote)}</blockquote><div class="claim-controls"><label>Data type<select data-claim-category="${i}" aria-label="Data type for claim ${i+1}">${Object.entries(CATEGORIES).map(([key,d])=>`<option value="${key}"${key===c.category?' selected':''}>${escape(d.label)}</option>`).join('')}</select></label><label>Interpretation<select data-claim-mode="${i}" aria-label="Interpretation for claim ${i+1}">${Object.entries(modeLabels).map(([key,label])=>`<option value="${key}"${key===c.mode?' selected':''}>${escape(label)}</option>`).join('')}</select></label></div><div class="claim-meta"><span>Line ${c.line} · characters ${c.start}–${c.end}</span><label class="claim-check"><input type="checkbox" data-claim-include="${i}"${c.included?' checked':''}> Include</label></div>${c.reason?`<p class="fine-print">${escape(c.reason)}</p>`:''}</article>`).join('');
 $('#results-content').innerHTML=`<div class="claim-review">${state.sample?'<span class="sample-tag">SYNTHETIC EXAMPLE</span>':''}<p class="section-kicker">POLICY → REVIEWED CLAIMS</p><h3>${state.claims.length?`${state.claims.length} claims to review`:'No supported claims found'}</h3><p class="subtle">Confirm what the policy says. Conditions and recipient-specific language stay undecided until you review them. This prototype supports precise location, email addresses, and device identifiers.</p><div class="claim-list">${cards}</div><button class="text-button" id="add-claim">+ Add selected policy text as a claim</button><p class="fine-print">Select a sentence in the policy box, then use this action if extraction missed it.</p>${!state.claims.length?'<div class="note-box">You can still inspect visible data, but “disclosure not located” may simply mean the extractor missed a statement.</div>':''}<label class="claim-check review-confirm"><input id="confirm-claims" type="checkbox"> I've checked the claims, conditions, and scope above.</label><div class="claim-actions"><button class="primary-button" id="run-button" disabled>Run evidence check <span aria-hidden="true">→</span></button></div><p class="fine-print">A match covers a data type in this capture. It is not a compliance finding.</p></div>`;
 $('#confirm-claims').addEventListener('change',e=>$('#run-button').disabled=!e.target.checked);$('#run-button').addEventListener('click',runAudit);
 $('#add-claim').addEventListener('click',()=>{const box=$('#policy');let start=box.selectionStart,end=box.selectionEnd;const quote=box.value.slice(start,end).trim();if(!quote){toast('Select the policy sentence in the text box first.');box.focus();return;}start+=box.value.slice(start,end).indexOf(quote);end=start+quote.length;if(state.claims.length>=150){toast('This review supports up to 150 claims.');return;}state.claims.push({id:`manual-${state.claims.length+1}`,category:'email',quote,start,end,line:box.value.slice(0,start).split('\n').length,mode:'review',originalMode:'review',included:true,reason:'Manually selected. Choose the relevant data type and interpretation.'});renderClaims();});
 for(const [attr,field] of [['mode','mode'],['category','category'],['include','included']])document.querySelectorAll(`[data-claim-${attr}]`).forEach(el=>el.addEventListener('change',()=>{state.claims[Number(el.getAttribute(`data-claim-${attr}`))][field]=attr==='include'?el.checked:el.value;$('#confirm-claims').checked=false;$('#run-button').disabled=true;}));
}
async function runAudit(){try{const policy=$('#policy').value,capture=state.capture,harText=state.harText,claims=structuredClone(state.claims);const r=audit({policy,claims,capture,context:$('#context').value,sample:state.sample});const hash=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');r.inputFingerprints={algorithm:'SHA-256',policy:await hash(policy),har:await hash(harText)};if(capture!==state.capture||policy!==$('#policy').value)return;state.report=r;state.phase='report';renderReport();scrollResults();}catch(error){showError(error.message);}}
function renderReport(){
 const r=state.report;setStateLabel('REVIEW COMPLETE');const attention=r.counts.conflict+r.counts.undisclosed;
 const findingHtml=r.findings.map((f,i)=>`<details class="finding"${i===0?' open':''}><summary><span class="finding-heading"><span class="finding-title">${escape(f.title)}</span><span class="status ${f.status}">${escape(STATUS[f.status].label)}</span></span></summary><div class="finding-body"><p>${escape(f.reason)}</p>${f.claims.length?f.claims.map(c=>`<div class="evidence-block"><h4>POLICY EVIDENCE · LINE ${c.line}</h4><blockquote>“${escape(c.quote)}”</blockquote><p class="evidence-path">Characters ${c.start}–${c.end} · ${escape(modeLabels[c.mode])}</p></div>`).join(''):'<div class="evidence-block"><h4>POLICY EVIDENCE</h4><blockquote>No matching included claim. Review the complete policy and referenced notices.</blockquote></div>'}${f.evidence.length?f.evidence.map(e=>`<div class="evidence-block"><h4>NETWORK EVIDENCE · REQUEST ${e.requestIndex+1}</h4><code>${escape(e.method)} → Destination ${e.destinationId}${e.host!=='[destination masked]'?' · '+escape(e.host):' · host masked'}</code><code>${escape(e.field)}: ${escape(e.maskedValue)}</code><p class="evidence-path">${escape(e.path)}</p><p class="fine-print">${escape(e.observation)}${e.timestamp?' '+escape(e.timestamp):''}</p></div>`).join(''):'<div class="evidence-block"><h4>NETWORK EVIDENCE</h4><blockquote>No recognized matching field in the visible requests.</blockquote></div>'}<div class="recommendation"><strong>Next step</strong> · ${escape(f.nextStep)}</div></div></details>`).join('');
 $('#results-content').innerHTML=`<div class="report">${r.sample?'<span class="sample-tag">SYNTHETIC EXAMPLE · NOT A REAL APP FINDING</span>':''}<div class="report-header"><div><p class="section-kicker">POLICY ↔ OBSERVED REQUESTS</p><h3>${attention?'A closer look is needed.':r.counts.unknown?'Some questions remain open.':r.findings.length?'Your evidence review is ready.':'No supported fields recognized.'}</h3><div class="report-meta">${r.coverage.requests} requests · ${r.coverage.destinations} destinations · ${r.coverage.reviewedClaims} reviewed claims</div></div><button class="text-button" id="edit-claims">Edit claims</button></div>${r.context?`<p class="subtle context-label">Test context: ${escape(r.context)}</p>`:''}<div class="report-overview"><div class="metric ${attention?'alert':''}"><strong>${attention.toString().padStart(2,'0')}</strong><span>Need investigation</span></div><div class="metric neutral"><strong>${r.counts.matched.toString().padStart(2,'0')}</strong><span>Disclosure matches</span></div><div class="metric"><strong>${(r.counts.unknown+r.counts.unobserved).toString().padStart(2,'0')}</strong><span>Open questions</span></div></div><p class="report-banner">${r.coverage.opaqueBodies?`${r.coverage.opaqueBodies} request bodies are omitted or unsupported. Missing data cannot establish that a promise was kept.`:'This review describes the supplied capture and supported fields. It does not prove the absence of collection or establish legal compliance.'}</p><div class="findings">${findingHtml||'<div class="note-box">No supported policy claims or network fields were recognized. Review the inputs manually or add a selected policy claim. This is not a passing result.</div>'}</div><details class="coverage"><summary>Capture coverage & what this cannot tell you</summary><p>${r.coverage.visibleBodies} supported visible request bodies; ${r.coverage.opaqueBodies} omitted or unsupported bodies. ${r.coverage.excludedClaims} claims excluded by the reviewer.</p>${r.coverage.warnings.map(w=>`<p>${escape(w)}</p>`).join('')}<ul>${r.limitations.map(l=>`<li>${escape(l)}</li>`).join('')}</ul></details><div class="report-actions"><button class="secondary-button" id="export-json">Download JSON ↓</button><button class="secondary-button" id="export-md">Download report ↓</button>${state.sample?'<button class="secondary-button" id="download-fixtures">Get sample inputs ↓</button>':''}</div><p class="fine-print">Portable reports omit raw values, policy quotes, detailed key paths, unknown hostnames, and test notes. Source offsets let you reopen the originals locally.</p></div>`;
 $('#edit-claims').addEventListener('click',()=>{state.phase='claims';state.report=null;renderClaims();});$('#export-json').addEventListener('click',()=>download('policytrace-report.json',JSON.stringify(exportReport(r),null,2),'application/json'));$('#export-md').addEventListener('click',()=>download('policytrace-report.md',reportMarkdown(r),'text/markdown'));$('#download-fixtures')?.addEventListener('click',()=>{download(`cedar-${state.sample}.har`,state.harText,'application/json');setTimeout(()=>download(`cedar-${state.sample}-policy.txt`,$('#policy').value,'text/plain'),300);});
 const reveal=document.createElement('button');reveal.className='text-button';reveal.id='show-destinations';reveal.textContent='Inspect destinations locally';$('.report-actions').before(reveal);reveal.addEventListener('click',()=>{const rows=JSON.parse(state.harText).log.entries;const hosts=new Map();rows.forEach((row,i)=>{const id=state.capture.requests[i].destinationId;if(!hosts.has(id))hosts.set(id,new URL(row.request.url).hostname);});openInfo('Captured destinations',`<p>These hostnames are shown only on your device. Unknown destination labels remain masked in exports. A hostname does not establish who operates the service or why data was sent.</p><ul>${[...hosts].map(([id,host])=>`<li><strong>Destination ${id}</strong> · <code>${escape(host)}</code></li>`).join('')}</ul>`);});
 if(r.inputFingerprints){const p=document.createElement('p');p.className='fine-print fingerprint';p.textContent=`Input fingerprints (SHA-256): policy ${r.inputFingerprints.policy.slice(0,12)}… · HAR ${r.inputFingerprints.har.slice(0,12)}… Full hashes are included in exports. They identify these input files; they do not prove capture authenticity.`;$('.coverage').append(p);}
}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared.');}
const methodHtml=`<h3>1. Bring a policy and a capture</h3><p>Paste a policy and load a HAR from a test session you are authorized to inspect. Everything is processed locally in your browser.</p><h3>2. Confirm the meaning</h3><p>A conservative, pattern-based extractor identifies English or Chinese statements about three data types. Review the source quotes and change their interpretation if needed. Conditional, recipient-specific, or ambiguous statements remain undecided.</p><h3>3. Inspect the trail</h3><p>The engine checks recognized fields in URLs, JSON request bodies, and form data. Findings link to exact policy offsets and HAR request indices. Coordinates must form a valid pair; a field name alone is not enough.</p><h3>Read results carefully</h3><p>“Observed disclosure match” covers only the reviewed data type. “Not observed” does not prove absence. “Disclosure not located” can mean the extractor missed a statement. “Potential contradiction” always needs a human to verify field semantics and policy scope.</p><p>Research background: <a href="https://www.usenix.org/conference/usenixsecurity20/presentation/andow" target="_blank" rel="noopener noreferrer">PoliCheck</a> and <a href="https://arxiv.org/abs/2210.06746" target="_blank" rel="noopener noreferrer">PoliGraph</a>. PolicyTrace is an independent prototype focused on reviewable, local workflows; it does not claim to invent flow-to-policy analysis.</p>`;
const privacyHtml=`<h3>Your files stay in this tab</h3><p>PolicyTrace sends no policy or HAR data to a server, uses no analytics, and stores no captures in browser storage. Reload or Clear removes the working session. The hosting provider handles ordinary website access requests.</p><h3>Exports are deliberately limited</h3><p>Reports omit raw request values, credentials, unknown hostname labels, URL paths, policy quotes, detailed JSON keys, and free-form test notes. They retain fixed data categories, source offsets, request indices, and timestamps. Review an export before sharing it; masking is not a guarantee of anonymity.</p><h3>Coverage</h3><p>Supported: email-shaped values in recognized email fields, values in recognized device identifier fields, and valid latitude/longitude pairs with at least four decimal places. Coordinates may be synthetic or refer to something other than the user. Arbitrary field names, request headers, response bodies, encoded or binary bodies, offline collection, retention, deletion, and server-side processing are outside scope.</p><h3>Policy interpretation</h3><p>The extractor is pattern-based, not a language model. It may miss statements or misunderstand wording. Review claims and keep uncertain cases undecided. Purpose, consent, recipient identity, legal duties, and capture authenticity are not established by this tool.</p><h3>Demonstration data</h3><p>Every bundled example is synthetic. Example domain names and identifiers do not represent a real company or person. Tests validate the prototype's stated behavior, not its accuracy across real-world apps.</p>`;
function openInfo(title,content){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=content;$('#info-dialog').showModal();}
$('#method-button').addEventListener('click',()=>openInfo('How PolicyTrace works',methodHtml));$('#privacy-button').addEventListener('click',()=>openInfo('Privacy & limitations',privacyHtml));$('#close-dialog').addEventListener('click',()=>$('#info-dialog').close());
$('#info-dialog').addEventListener('click',e=>{if(e.target===$('#info-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#review-button').addEventListener('click',reviewClaims);$('#policy').addEventListener('input',()=>{state.sample=null;invalidate();setSampleSelection();showError('');});$('#context').addEventListener('input',()=>{if(state.report){state.report.context=$('#context').value;renderReport();}});$('#har-file').addEventListener('change',e=>loadHar(e.target.files[0]));
$('#policy-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>800000)throw new Error('Policy text is limited to 200,000 characters.');const text=await file.text();if(text.length>200000)throw new Error('Policy text is limited to 200,000 characters.');$('#policy').value=text;state.sample=null;invalidate();setSampleSelection();showError('');}catch(error){showError(error.message);}});
$('#clear-button').addEventListener('click',()=>{state.readVersion++;Object.assign(state,{capture:null,harText:null,fileName:null,sample:null,report:null,claims:[],phase:'input'});$('#policy').value='';$('#context').value='';$('#har-file').value='';$('#policy-file').value='';$('#har-label').textContent='Choose a HAR file';$('#har-help').textContent='or drop it here · .har / .json · up to 10 MB';$('#results-content').innerHTML=emptyHtml;setStateLabel('READY WHEN YOU ARE');showError('');ready();setSampleSelection();toast('Review cleared from this tab.');});
document.addEventListener('click',e=>{const button=e.target.closest('[data-demo]');if(button)loadExample(button.dataset.demo);});for(const type of ['dragenter','dragover'])$('#dropzone').addEventListener(type,e=>{e.preventDefault();$('#dropzone').classList.add('dragging');});for(const type of ['dragleave','drop'])$('#dropzone').addEventListener(type,e=>{e.preventDefault();$('#dropzone').classList.remove('dragging');if(type==='drop')loadHar(e.dataTransfer.files[0]);});ready();
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();const registrations=[{name:'load_privacy_audit_example',title:'Open a PolicyTrace example',description:'Load a synthetic example and stage its policy claims for visible human review. Does not complete an audit.',inputSchema:{type:'object',properties:{example:{type:'string',enum:Object.keys(EXAMPLES)}},required:['example'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='example')||!Object.hasOwn(EXAMPLES,input.example))throw new Error('Choose a valid example.');return loadExample(input.example);}},{name:'read_privacy_audit_summary',title:'Read the current review summary',description:'Read counts from an audit already completed through the visible interface. No policy text or raw capture data is returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');if(!state.report)return {phase:state.phase,completed:false};return {completed:true,counts:{...state.report.counts},coverage:{requests:state.report.coverage.requests,opaqueBodies:state.report.coverage.opaqueBodies},synthetic:!!state.report.sample};}}];for(const tool of registrations){try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
